const fs = require('fs');
const path = require('path');
const http = require('http');

const ENDPOINT = process.env.STATUS_ENDPOINT || 'http://127.0.0.1:49684/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

http.get(ENDPOINT, (res) => {
  let body = '';
  res.on('data', (chunk) => (body += chunk));
  res.on('end', () => {
    if (res.statusCode !== 200) {
      console.error(`Unexpected status code: ${res.statusCode}`);
      process.exit(1);
    }
    let data;
    try {
      data = JSON.parse(body);
    } catch (err) {
      console.error('Failed to parse JSON response:', err.message);
      process.exit(1);
    }
    fs.mkdirSync(OUT_DIR, { recursive: true });
    fs.writeFileSync(OUT_FILE, JSON.stringify({ status: data.status }, null, 2) + '\n');
    console.log(`status=${data.status} written to ${OUT_FILE}`);
  });
}).on('error', (err) => {
  console.error('Request failed:', err.message);
  process.exit(1);
});

